          return { slug: x[0], nom: x[1], brasserie: x[2], type: x[3], robe: "#" + x[4], sur: "#" + x[5], forme: "#" + x[6],
                   valeurs: x[7].split(",").map(Number), estimee: !!x[8], conseil: !!x[9],
                   cle: plat(x[1] + " " + x[2]), cleNom: plat(x[1]) };
